def spiralValueAt(x, y):
    m = max(abs(x), abs(y))
    if m == 0:
        return 1
    base = (2 * m - 1) ** 2
    if x == m and y >= -(m - 1):
        off = y + m
    elif y == m and x <= m - 1:
        off = 2 * m + (m - x)
    elif x == -m and y <= m - 1:
        off = 4 * m + (m - y)
    else:
        off = 6 * m + (x + m)
    return base + off
